public class WordChampionTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("simple repeat", "the", WordChampion.mostCommonWord("the cat and the hat"));
        check("case and punctuation ignored", "hello", WordChampion.mostCommonWord("Hello, hello... WORLD!"));
        check("tie broken alphabetically", "is", WordChampion.mostCommonWord("It is what it is."));
        check("tie among later words", "three", WordChampion.mostCommonWord("one two two three three"));
        check("single word", "solo", WordChampion.mostCommonWord("solo"));
        check("empty text", "", WordChampion.mostCommonWord(""));
        check("no letters at all", "", WordChampion.mostCommonWord("123 ... 456"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

