public class WordChampion {

    public static String mostCommonWord(String text) {
        java.util.Map<String, Long> counts = java.util.Arrays
                .stream(text.toLowerCase(java.util.Locale.ROOT).split("[^a-z]+"))
                .filter(w -> !w.isEmpty())
                .collect(java.util.stream.Collectors.groupingBy(
                        w -> w, java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
                .sorted(java.util.Map.Entry.<String, Long>comparingByValue().reversed()
                        .thenComparing(java.util.Map.Entry.comparingByKey()))
                .map(java.util.Map.Entry::getKey)
                .findFirst()
                .orElse("");
    }
}
